function createPage(host2) {
  setReact(host2.React);
  return function OmpSessionsPage() {
    const [view, setView] = useState("sessions");
    const [overview, setOverview] = useState(null);
    const [overviewError, setOverviewError] = useState(null);
    const [sessions, setSessions] = useState(null);
    const [error, setError] = useState(null);
    const [refreshedAt, setRefreshedAt] = useState(null);
    const [now, setNow] = useState(Date.now());
    const [selected, setSelected] = useState(null);
    const [creating, setCreating] = useState(false);
    const [query, setQuery] = useState("");
    const [board, setBoard] = useState("");
    const [group, setGroup] = useState("");
    const [project, setProject] = useState("");
    const [archived, setArchived] = useState(false);
    const [notice, setNotice] = useState(null);
    const search = useRef(null);
    const loadSessions = async () => {
      try {
        const res = await host2.request("/sessions");
        setSessions(res.sessions);
        setError(null);
        setRefreshedAt(Date.now());
      } catch (err) {
        setError(errorMessage(err));
      }
      setNow(Date.now());
    };
    const loadOverview = async () => {
      try {
        setOverview(await host2.request("/overview"));
        setOverviewError(null);
      } catch (err) {
        setOverviewError(errorMessage(err));
      }
    };
    const refresh = () => {
      void loadSessions();
      void loadOverview();
    };
    usePoll(loadSessions, SESSIONS_MS);
    usePoll(loadOverview, OVERVIEW_MS);
    useEffect(() => {
      const onKey = (e) => {
        const t = e.target instanceof HTMLElement ? e.target : null;
        if (e.metaKey || e.ctrlKey || e.altKey || t?.closest("input, textarea, select, [contenteditable='true'], [role='dialog']")) return;
        if (e.key === "/" && view === "sessions") {
          e.preventDefault();
          search.current?.focus();
        } else if (e.key === "n" || e.key === "N") {
          e.preventDefault();
          setCreating(true);
        }
      };
      window.addEventListener("keydown", onKey);
      return () => window.removeEventListener("keydown", onKey);
    }, [view]);
    const all = sessions ?? [];
    const facets = useMemo(() => {
      const uniq = (xs) => [...new Set(xs.filter((x) => Boolean(x)))].sort((a, b) => a.localeCompare(b));
      return { boards: uniq(all.map(boardOf)), groups: uniq(all.map((s) => s.group)), projects: uniq(all.map((s) => s.project)) };
    }, [sessions]);
    const q = query.trim().toLowerCase();
    const shown = all.filter(
      (s) => (archived || !s.archived) && (!board || boardOf(s) === board) && (!group || s.group === group) && (!project || s.project === project) && (!q || [s.title, s.cwd, s.excerpt ?? "", s.id, s.group ?? "", s.card?.title ?? "", ...s.tags].some((x) => x.toLowerCase().includes(q)))
    );
    const filtered = Boolean(q || board || group || project);
    const archivedCount = all.filter((s) => s.archived).length;
    const started = (s) => {
      setCreating(false);
      setView("sessions");
      setSelected(s.id);
      refresh();
    };
    const openProject = async (id) => {
      setNotice(null);
      try {
        setNotice(await openInVscode(host2, `/sessions/${encodeURIComponent(id)}/project`));
      } catch (err) {
        setNotice(errorMessage(err));
      }
    };
    const notInstalled = overview && !overview.ompSessions.found;
    let main;
    if (view === "boards") {
      main = h(BoardsPanel, { host: host2, lane: overview?.lane ?? null, now, onChanged: () => void loadOverview(), onOpenSession: (id) => (setView("sessions"), setSelected(id)) });
    } else if (notInstalled) {
      main = h(Empty, { icon: "terminal", title: "omp-sessions is not installed", body: overview.ompSessions.hint ?? "", action: h(Button, { label: "Check again", icon: "refresh", onClick: refresh }) });
    } else if (!sessions) {
      main = error ? h(ErrorBox, { message: error, onRetry: refresh }) : h("div", { className: "omps-loading" }, h("span", { className: "omps-spinner" }), "Loading sessions…");
    } else if (all.length === 0) {
      main = h(Empty, {
        icon: "sparkle",
        title: "No omp sessions yet",
        body: "Start one here, with omp-sessions new, from VS Code or the omp phone app, or ask Hermes to (the omp_session_start tool). Kanban cards assigned to omp show up here too once the lane is on.",
        action: h(Button, { kind: "brand", icon: "plus", label: "New session", onClick: () => setCreating(true) })
      });
    } else {
      main = h(
        "div",
        { className: "omps-main" },
        h(
          "div",
          { className: "omps-filters" },
          h(
            "label",
            { className: "omps-search" },
            icon("search", 14),
            h("input", { ref: search, type: "search", value: query, placeholder: "Search sessions  /", "aria-label": "Search sessions", onChange: (e) => setQuery(e.target.value) })
          ),
          h(Select, { label: "Board", value: board, all: "All boards", options: facets.boards, onChange: setBoard }),
          h(Select, { label: "Group", value: group, all: "All groups", options: facets.groups, onChange: setGroup }),
          h(Select, { label: "Project", value: project, all: "All projects", options: facets.projects, onChange: setProject }),
          archivedCount ? h(Button, { small: true, kind: archived ? "primary" : "ghost", pressed: archived, label: `Archived · ${archivedCount}`, onClick: () => setArchived(!archived) }) : null,
          filtered ? h(Button, { small: true, kind: "ghost", icon: "x", label: "Clear", onClick: () => (setQuery(""), setBoard(""), setGroup(""), setProject("")) }) : null,
          h("span", { className: "omps-grow" }),
          h("span", { className: "omps-muted omps-total" }, filtered ? `${shown.length} of ${all.length}` : `${all.length} session${all.length === 1 ? "" : "s"}`)
        ),
        error ? h("div", { className: "omps-stale" }, icon("alert", 12), `Not refreshed: ${error}`) : null,
        notice ? h("div", { className: "omps-notice" }, icon("external", 12), notice) : null,
        h(SessionBoard, { sessions: shown, selected, now, onOpen: setSelected, onOpenProject: (id) => void openProject(id), filtered })
      );
    }
    return h(
      "div",
      { className: cx("omps", `omps-host-${host2.kind}`, selected && view === "sessions" && "has-drawer") },
      host2.css ? h("style", null, host2.css) : null,
      h(
        "header",
        { className: "omps-head" },
        logo(30),
        h("div", { className: "omps-head-titles" }, h("h1", { className: "omps-title" }, "omp Sessions"), overview ? h("span", { className: "omps-profile", title: "Hermes profile" }, overview.profile) : null),
        h(Segmented, {
          label: "View",
          value: view,
          onChange: setView,
          options: [
            { value: "sessions", label: "Sessions" },
            { value: "boards", label: "Boards" }
          ]
        }),
        h("span", { className: "omps-grow" }),
        h(Button, { kind: "ghost", icon: "refresh", title: "Refresh", onClick: refresh }),
        h(Button, { kind: "brand", icon: "plus", label: "New session", title: "New session (N)", disabled: Boolean(notInstalled), onClick: () => setCreating(true) })
      ),
      h(StatusStrip, { o: overview, error: overviewError, sessions, now, refreshedAt, onBoards: () => setView("boards") }),
      // Desktop keeps its own copy of this page; after a plugin update it can lag the backend it talks to.
      host2.kind === "desktop" && overview?.pluginVersion && overview.pluginVersion !== "0.6.0" ? h(Notes, {
        className: "omps-page-note",
        notes: [
          `This page is omp Sessions ${"0.6.0"}; the plugin on this Hermes is ${overview.pluginVersion}. Update the page in Capabilities → Plugins → omp Sessions: Rescan when Hermes runs on this computer, or Install from Git again with Force reinstall when it runs on another machine.`
        ]
      }) : null,
      h("div", { className: "omps-body" }, main),
      selected && view === "sessions" ? h(DetailPanel, { key: selected, host: host2, id: selected, summary: all.find((s) => s.id === selected), now, onClose: () => setSelected(null), onChanged: () => void loadSessions() }) : null,
      creating ? h(NewSessionDialog, { host: host2, groups: facets.groups, onClose: () => setCreating(false), onStarted: started }) : null
    );
  };
}

// integrations/hermes/ui/style.css
var style_default = `/* omp Sessions page: one stylesheet for the Hermes dashboard (--color-* tokens) and Hermes Desktop
 * (--ui-* tokens). Everything is scoped under .omps; colors come from the host theme, with the omp
 * brand (pink → violet → cyan) for state accents. */

/* Dashboard tokens (--color-*; text is --color-card-foreground: the dashboard defines no
 * --color-foreground). It also defines some --ui-* variables that don't follow its theme, so each
 * host maps only its own tokens. */
.omps {
	--o-fg: var(--color-card-foreground, var(--midground, #ece8f2));
	--o-fg2: color-mix(in srgb, var(--o-fg) 82%, transparent);
	--o-muted: var(--color-muted-foreground, color-mix(in srgb, var(--o-fg) 60%, transparent));
	--o-faint: color-mix(in srgb, var(--o-fg) 45%, transparent);
	--o-bg: var(--color-card, #0c0812);
	--o-card: var(--color-card, color-mix(in srgb, var(--o-fg) 4%, transparent));
	--o-col: color-mix(in srgb, var(--o-fg) 3%, transparent);
	--o-raised: var(--color-popover, var(--o-bg));
	/* An opaque surface under overlays (the drawer, the dialog). */
	--o-solid: var(--color-card, #0c0812);
	--o-hover: color-mix(in srgb, var(--o-fg) 7%, transparent);
	--o-border: var(--color-border, color-mix(in srgb, var(--o-fg) 14%, transparent));
	--o-border-strong: color-mix(in srgb, var(--o-fg) 26%, transparent);
	--o-accent: var(--color-primary, #9b4dff);
	--o-accent-fg: var(--color-card, #fff);
	--o-ring: var(--color-ring, #b383ff);
	--o-red: var(--color-destructive, #e5484d);
	--o-green: var(--color-success, #30a46c);
	--o-yellow: var(--color-warning, #e2b203);
	--o-blue: #3b9eff;
	--o-purple: #9b4dff;
	--o-pink: #ed4abf;
	--o-cyan: #5ad8e6;
	--o-grad: linear-gradient(100deg, #ed4abf 0%, #9b4dff 52%, #5ad8e6 100%);
	--o-radius: 10px;
	--o-radius-sm: 7px;
	--t-needs_input: var(--o-pink);
	--t-working: var(--o-blue);
	--t-starting: var(--o-blue);
	--t-queued: var(--o-purple);
	--t-scheduled: var(--o-purple);
	--t-interrupted: var(--o-yellow);
	--t-idle: var(--o-green);
	--t-stopped: color-mix(in srgb, var(--o-fg) 38%, transparent);

	position: relative;
	color: var(--o-fg);
	font-size: 13px;
	line-height: 1.45;
	-webkit-font-smoothing: antialiased;
}
/* Desktop tokens (--ui-*). */
.omps.omps-host-desktop {
	--o-fg: var(--ui-text-primary, #ece8f2);
	--o-fg2: var(--ui-text-secondary, color-mix(in srgb, var(--o-fg) 82%, transparent));
	--o-muted: var(--ui-text-tertiary, color-mix(in srgb, var(--o-fg) 60%, transparent));
	--o-faint: var(--ui-text-quaternary, color-mix(in srgb, var(--o-fg) 45%, transparent));
	--o-bg: var(--ui-surface-background, var(--ui-bg-editor, transparent));
	--o-card: var(--ui-bg-card, color-mix(in srgb, var(--o-fg) 4%, transparent));
	--o-raised: var(--ui-bg-elevated, var(--o-bg));
	--o-solid: var(--ui-chat-surface-background, var(--ui-surface-background, var(--ui-bg-editor, #fff)));
	--o-border: var(--ui-stroke-secondary, color-mix(in srgb, var(--o-fg) 14%, transparent));
	--o-border-strong: var(--ui-stroke-primary, color-mix(in srgb, var(--o-fg) 26%, transparent));
	--o-accent: var(--ui-accent, #9b4dff);
	--o-accent-fg: #fff;
	--o-ring: var(--ui-accent, #b383ff);
	--o-red: var(--ui-red, #e5484d);
	--o-green: var(--ui-green, #30a46c);
	--o-yellow: var(--ui-yellow, #e2b203);
	--o-blue: var(--ui-blue, #3b9eff);
	--o-purple: var(--ui-purple, #9b4dff);
	--o-cyan: var(--ui-cyan, #5ad8e6);
}
.omps *, .omps *::before, .omps *::after { box-sizing: border-box; }
/* Themes paint <code>/<pre> with accent fills; ours read as text on our own surfaces. */
.omps code, .omps pre { background: transparent; color: inherit; border: 0; box-shadow: none; padding: 0; font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, Consolas, monospace); font-size: 0.92em; }
/* :where() keeps this reset at zero specificity, so .omps-btn-primary and friends set their own color. */
:where(.omps) :where(button, input, select, textarea) { font: inherit; color: inherit; letter-spacing: inherit; }
.omps :focus-visible { outline: 2px solid var(--o-ring); outline-offset: 2px; }
.omps-grow { flex: 1; }
.omps-muted { color: var(--o-muted); }
.omps-hint { color: var(--o-faint); font-size: 11.5px; }
.omps-mono { font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, Consolas, monospace); font-size: 12px; }
.omps-icon { flex: none; display: inline-block; vertical-align: -2px; }

/* Desktop: the page fills its workspace pane and scrolls inside. */
.omps-host-desktop { height: 100%; display: flex; flex-direction: column; overflow: hidden; background: var(--o-bg); }
.omps-host-desktop .omps-head { padding: 14px 18px 0; }
.omps-host-desktop .omps-strip { margin: 10px 18px 0; }
/* The stale-page note sits between the strip and the board (Desktop only). */
.omps-host-desktop .omps-page-note { flex: none; margin: 8px 18px 0; padding: 7px 12px; border-radius: var(--o-radius); border: 1px solid color-mix(in srgb, var(--o-yellow) 40%, var(--o-border)); background: color-mix(in srgb, var(--o-yellow) 7%, transparent); }
.omps-host-desktop .omps-body { flex: 1; min-height: 0; overflow: auto; padding: 12px 18px 24px; }
.omps-host-dashboard .omps-body { padding-top: 12px; }

/* ---------- header ---------- */
.omps-head { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.omps-logo { flex: none; filter: drop-shadow(0 4px 14px rgba(155, 77, 255, 0.35)); }
.omps-head-titles { display: flex; align-items: baseline; gap: 8px; margin-right: 6px; }
.omps-title { margin: 0; font-size: 18px; font-weight: 650; letter-spacing: -0.01em; color: var(--o-fg); }
.omps-profile { font-size: 11px; padding: 1px 8px; border-radius: 999px; border: 1px solid var(--o-border); color: var(--o-muted); }
/* The dashboard's page header already names the tab. */
.omps-host-dashboard .omps-title { display: none; }

/* ---------- buttons ---------- */
.omps-btn {
	display: inline-flex; align-items: center; justify-content: center; gap: 6px;
	height: 32px; padding: 0 12px; border-radius: var(--o-radius-sm);
	border: 1px solid var(--o-border); background: var(--o-card); color: var(--o-fg);
	font-weight: 550; white-space: nowrap; cursor: pointer;
	transition: background 0.12s, border-color 0.12s, box-shadow 0.12s, transform 0.06s;
}
.omps-btn:hover:not(:disabled) { background: var(--o-hover); border-color: var(--o-border-strong); }
.omps-btn:active:not(:disabled) { transform: translateY(1px); }
.omps-btn:disabled { opacity: 0.5; cursor: default; }
.omps-btn-sm { height: 27px; padding: 0 9px; font-size: 12px; gap: 5px; }
.omps-btn-icon { width: 32px; padding: 0; }
.omps-btn-sm.omps-btn-icon { width: 27px; }
.omps-btn-ghost { background: transparent; border-color: transparent; color: var(--o-fg2); }
.omps-btn-ghost:hover:not(:disabled) { background: var(--o-hover); border-color: transparent; color: var(--o-fg); }
.omps-btn-primary { background: var(--o-accent); border-color: transparent; color: var(--o-accent-fg); }
.omps-btn-primary:hover:not(:disabled) { background: color-mix(in srgb, var(--o-accent) 86%, var(--o-fg)); border-color: transparent; }
.omps-btn-danger { background: color-mix(in srgb, var(--o-red) 14%, transparent); border-color: color-mix(in srgb, var(--o-red) 45%, transparent); color: var(--o-red); }
.omps-btn-danger:hover:not(:disabled) { background: color-mix(in srgb, var(--o-red) 22%, transparent); border-color: var(--o-red); }
/* Pink → violet only: white text stays above 4.5:1 across the whole button (the cyan end would not). */
.omps-btn-brand { background: linear-gradient(100deg, #c42a92 0%, #7c3aed 100%); border: 0; color: #fff; box-shadow: 0 8px 24px -12px rgba(155, 77, 255, 0.8); text-shadow: 0 1px 1px rgba(0, 0, 0, 0.2); }
.omps-btn-brand:hover:not(:disabled) { filter: brightness(1.08); box-shadow: 0 10px 28px -10px rgba(155, 77, 255, 0.9); }
.omps-btn[aria-pressed="true"]:not(.omps-btn-primary) { border-color: var(--o-accent); }
/* Desktop's own pages use one solid accent for their primary action; the brand gradient stays in the dashboard. */
.omps-host-desktop .omps-btn-brand { background: var(--o-accent); color: var(--o-accent-fg); box-shadow: none; text-shadow: none; }
.omps-host-desktop .omps-btn-brand:hover:not(:disabled) { filter: none; background: color-mix(in srgb, var(--o-accent) 86%, var(--o-fg)); box-shadow: none; }
.omps-spinner { width: 13px; height: 13px; border-radius: 50%; border: 2px solid currentColor; border-top-color: transparent; display: inline-block; animation: omps-spin 0.8s linear infinite; flex: none; }
@keyframes omps-spin { to { transform: rotate(360deg); } }

/* ---------- segmented / switch ---------- */
.omps-seg { display: inline-flex; padding: 2px; gap: 2px; border-radius: 9px; background: color-mix(in srgb, var(--o-fg) 6%, transparent); border: 1px solid var(--o-border); flex-wrap: wrap; }
.omps-seg-item { border: 0; background: transparent; color: var(--o-muted); height: 27px; padding: 0 12px; border-radius: 7px; cursor: pointer; font-weight: 550; }
.omps-seg-item:hover:not(:disabled) { color: var(--o-fg); }
.omps-seg-item.is-on { background: var(--o-raised); color: var(--o-fg); box-shadow: 0 1px 2px rgba(0, 0, 0, 0.18), 0 0 0 1px var(--o-border); }
.omps-seg-sm .omps-seg-item { height: 24px; padding: 0 9px; font-size: 12px; }
.omps-switch { position: relative; width: 36px; height: 20px; flex: none; border-radius: 999px; border: 1px solid var(--o-border-strong); background: color-mix(in srgb, var(--o-fg) 12%, transparent); cursor: pointer; padding: 0; transition: background 0.15s, border-color 0.15s; }
.omps-switch-knob { position: absolute; top: 2px; left: 2px; width: 14px; height: 14px; border-radius: 50%; background: var(--o-fg); transition: transform 0.15s; }
.omps-switch.is-on { background: var(--o-green); border-color: transparent; }
.omps-switch.is-on .omps-switch-knob { transform: translateX(16px); background: #fff; }
.omps-switch.is-busy { opacity: 0.6; }
.omps-switch:disabled { cursor: default; }

/* ---------- status strip ---------- */
.omps-strip {
	display: flex; align-items: center; flex-wrap: wrap; gap: 4px 18px;
	margin-top: 12px; padding: 8px 14px; border-radius: var(--o-radius);
	border: 1px solid var(--o-border); background: var(--o-card);
	font-size: 12.5px; color: var(--o-fg2);
	position: relative; overflow: hidden;
}
.omps-strip::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: var(--o-grad); }
.omps-strip-item { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
.omps-strip-item strong { color: var(--o-fg); font-weight: 600; }
.omps-strip-btn { border: 0; background: transparent; padding: 2px 6px; margin: -2px -6px; border-radius: 6px; cursor: pointer; color: inherit; }
.omps-strip-btn:hover { background: var(--o-hover); }
.omps-strip-need { color: var(--o-pink); font-weight: 600; }
.omps-strip-time { display: inline-flex; align-items: center; gap: 4px; color: var(--o-faint); font-size: 11.5px; }
.omps-strip-btn.is-warn > .omps-icon { color: var(--o-yellow); }
.omps-notes { list-style: none; margin: 8px 0 0; padding: 0; display: flex; flex-direction: column; gap: 3px; font-size: 12px; color: color-mix(in srgb, var(--o-yellow) 72%, var(--o-fg)); }
.omps-notes li { display: flex; align-items: flex-start; gap: 6px; }
.omps-notes .omps-icon { margin-top: 2px; color: var(--o-yellow); }
.omps-strip-notes { flex-basis: 100%; margin: 2px 0 0; padding-top: 7px; border-top: 1px dashed var(--o-border); white-space: normal; }
.omps-led { width: 8px; height: 8px; border-radius: 50%; flex: none; background: var(--o-faint); }
.omps-led.is-ok { background: var(--o-green); box-shadow: 0 0 0 3px color-mix(in srgb, var(--o-green) 22%, transparent); }
.omps-led.is-warn { background: var(--o-yellow); box-shadow: 0 0 0 3px color-mix(in srgb, var(--o-yellow) 22%, transparent); }
.omps-led.is-bad { background: var(--o-red); box-shadow: 0 0 0 3px color-mix(in srgb, var(--o-red) 22%, transparent); }
.omps-slots { display: inline-flex; gap: 3px; }
.omps-slot { width: 7px; height: 12px; border-radius: 2px; border: 1px solid var(--o-border-strong); }
.omps-slot.is-used { background: var(--o-blue); border-color: transparent; box-shadow: 0 0 8px -1px color-mix(in srgb, var(--o-blue) 70%, transparent); }

/* ---------- filters ---------- */
.omps-filters { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; margin-bottom: 12px; }
.omps-search { display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 10px; min-width: 240px; border-radius: var(--o-radius-sm); border: 1px solid var(--o-border); background: var(--o-card); color: var(--o-muted); }
.omps-search:focus-within { border-color: var(--o-ring); }
.omps-search input { border: 0; outline: 0; background: transparent; flex: 1; min-width: 0; color: var(--o-fg); }
.omps-search input::placeholder { color: var(--o-faint); }
.omps-filter { display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 4px 0 10px; border-radius: var(--o-radius-sm); border: 1px solid var(--o-border); background: var(--o-card); }
.omps-filter.is-set { border-color: var(--o-accent); }
.omps-filter-label { color: var(--o-muted); font-size: 12px; }
.omps-filter select { border: 0; background: transparent; color: var(--o-fg); padding: 0 4px; height: 28px; cursor: pointer; max-width: 180px; color-scheme: light dark; }
.omps-filter select option { background: var(--o-raised); color: var(--o-fg); }
.omps-total { font-size: 12px; }
.omps-stale { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--o-yellow); margin: -4px 0 10px; }
.omps-notice { display: flex; align-items: baseline; gap: 6px; font-size: 12px; color: var(--o-muted); margin: -4px 0 10px; }

/* ---------- board ---------- */
/* Columns wrap instead of scrolling sideways in a narrow pane; empty ones take less room. */
.omps-board { display: flex; flex-wrap: wrap; gap: 12px; align-items: flex-start; }
.omps-col { flex: 1 1 232px; min-width: 0; border-radius: calc(var(--o-radius) + 2px); border: 1px solid var(--o-border); background: var(--o-col); display: flex; flex-direction: column; }
.omps-col.is-empty { flex-basis: 168px; }
.omps-col-head { display: flex; align-items: center; gap: 7px; padding: 10px 12px 9px; border-bottom: 1px solid var(--o-border); font-weight: 600; font-size: 12.5px; position: relative; }
.omps-col-head::after { content: ""; position: absolute; left: 12px; right: 12px; bottom: -1px; height: 2px; border-radius: 2px; background: var(--tone, var(--o-border)); opacity: 0.85; }
.col-needs { --tone: var(--t-needs_input); }
.col-working { --tone: var(--t-working); }
.col-queued { --tone: var(--t-queued); }
.col-done { --tone: var(--t-idle); }
.col-stopped { --tone: var(--t-stopped); }
.col-queued { border-style: dashed; }
.omps-col-icon { color: var(--tone); display: inline-flex; }
.omps-col-title { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.omps-count { min-width: 22px; height: 19px; padding: 0 7px; border-radius: 999px; display: inline-flex; align-items: center; justify-content: center; font-size: 11px; font-variant-numeric: tabular-nums; background: color-mix(in srgb, var(--tone, var(--o-fg)) 16%, transparent); color: var(--o-fg); }
.col-needs .omps-count { background: var(--o-pink); color: #fff; }
.col-needs:has(.omps-card) { border-color: color-mix(in srgb, var(--o-pink) 45%, var(--o-border)); box-shadow: 0 0 0 1px color-mix(in srgb, var(--o-pink) 14%, transparent), 0 18px 40px -28px color-mix(in srgb, var(--o-pink) 60%, transparent); }
.omps-col-body { display: flex; flex-direction: column; gap: 8px; padding: 8px; min-height: 64px; }
.omps-more { border: 1px dashed var(--o-border); background: transparent; color: var(--o-muted); border-radius: var(--o-radius-sm); padding: 6px; cursor: pointer; }
.omps-more:hover { color: var(--o-fg); background: var(--o-hover); }

/* ---------- cards ---------- */
.omps-card {
	--tone: var(--t-stopped);
	position: relative; display: flex; flex-direction: column; gap: 6px;
	padding: 10px 11px 9px 13px; border-radius: var(--o-radius);
	border: 1px solid var(--o-border); background: var(--o-raised);
	cursor: pointer; overflow: hidden;
	box-shadow: 0 1px 2px rgba(0, 0, 0, 0.12);
	transition: border-color 0.12s, box-shadow 0.12s, transform 0.12s;
}
.omps-card::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: var(--tone); }
.omps-card:hover { border-color: var(--o-border-strong); transform: translateY(-1px); box-shadow: 0 10px 24px -16px rgba(0, 0, 0, 0.55); }
.omps-card.is-selected { border-color: var(--tone); box-shadow: 0 0 0 1px var(--tone), 0 10px 26px -16px color-mix(in srgb, var(--tone) 80%, transparent); }
.omps-card.is-archived { opacity: 0.6; }
.tone-needs_input { --tone: var(--t-needs_input); }
.tone-working { --tone: var(--t-working); }
.tone-starting { --tone: var(--t-starting); }
.tone-queued { --tone: var(--t-queued); }
.tone-scheduled { --tone: var(--t-scheduled); }
.tone-interrupted { --tone: var(--t-interrupted); }
.tone-idle { --tone: var(--t-idle); }
.tone-stopped, .tone-removed { --tone: var(--t-stopped); }
.omps-card.tone-needs_input { background: linear-gradient(180deg, color-mix(in srgb, var(--o-pink) 9%, var(--o-raised)), var(--o-raised) 70%); }
.omps-card-top { display: flex; align-items: flex-start; gap: 7px; min-width: 0; }
.omps-card-top .omps-dot { margin-top: 6px; }
.omps-card-top .omps-mode { margin-top: 1px; }
.omps-dot { width: 8px; height: 8px; border-radius: 50%; flex: none; background: var(--tone); }
.omps-dot.tone-working, .omps-dot.tone-starting { box-shadow: 0 0 0 3px color-mix(in srgb, var(--tone) 25%, transparent); animation: omps-breathe 1.8s ease-in-out infinite; }
.omps-dot.tone-needs_input { box-shadow: 0 0 0 3px color-mix(in srgb, var(--tone) 28%, transparent); }
@keyframes omps-breathe { 50% { box-shadow: 0 0 0 5px color-mix(in srgb, var(--tone) 6%, transparent); } }
.omps-card-title { flex: 1; min-width: 0; font-weight: 600; font-size: 13.5px; line-height: 1.35; color: var(--o-fg); overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow-wrap: anywhere; }
.omps-mode { flex: none; font-size: 10.5px; font-weight: 600; letter-spacing: 0.02em; text-transform: uppercase; padding: 1px 6px; border-radius: 5px; border: 1px solid var(--o-border); color: var(--o-muted); }
.omps-mode.mode-auto { color: var(--o-yellow); border-color: color-mix(in srgb, var(--o-yellow) 45%, transparent); }
.omps-mode.mode-plan { color: var(--o-cyan); border-color: color-mix(in srgb, var(--o-cyan) 45%, transparent); }
.omps-mode.mode-edits { color: var(--o-blue); border-color: color-mix(in srgb, var(--o-blue) 40%, transparent); }
.omps-card-meta { display: flex; align-items: center; gap: 6px; min-width: 0; color: var(--o-muted); font-size: 12px; }
.omps-card-project { display: inline-flex; align-items: center; gap: 4px; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.omps-card-vscode { display: inline-flex; align-items: center; padding: 2px; border: 0; border-radius: 4px; background: none; color: var(--o-faint); cursor: pointer; opacity: 0; }
.omps-card:hover .omps-card-vscode, .omps-card:focus-within .omps-card-vscode, .omps-card-vscode:focus-visible { opacity: 1; }
.omps-card-vscode:hover { color: var(--o-fg); background: var(--o-hover); }
.omps-chip { display: inline-flex; align-items: center; gap: 4px; max-width: 150px; padding: 0 7px; height: 19px; border-radius: 999px; font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; background: color-mix(in srgb, var(--o-accent) 14%, transparent); color: var(--o-fg2); border: 1px solid color-mix(in srgb, var(--o-accent) 24%, transparent); }
.omps-chip.is-warn { background: color-mix(in srgb, var(--o-yellow) 16%, transparent); border-color: color-mix(in srgb, var(--o-yellow) 40%, transparent); }
.omps-chip.is-needs { background: color-mix(in srgb, var(--o-pink) 16%, transparent); border-color: color-mix(in srgb, var(--o-pink) 40%, transparent); }
.omps-chip-btn { cursor: pointer; height: 24px; padding: 0 9px; }
.omps-chip-btn:hover { border-color: var(--o-accent); color: var(--o-fg); }
.omps-card-excerpt { color: var(--o-fg2); font-size: 12px; line-height: 1.45; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.omps-card-excerpt.is-warn { color: var(--o-yellow); }
.omps-card-question { border-radius: var(--o-radius-sm); padding: 7px 9px; background: color-mix(in srgb, var(--o-pink) 10%, transparent); border: 1px solid color-mix(in srgb, var(--o-pink) 30%, transparent); }
.omps-card-question-text { font-weight: 550; font-size: 12.5px; color: var(--o-fg); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.omps-card-options { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 6px; }
.omps-option-chip { font-size: 11px; padding: 1px 7px; border-radius: 5px; background: var(--o-raised); border: 1px solid var(--o-border); color: var(--o-fg2); max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.omps-option-more { font-size: 11px; color: var(--o-muted); padding: 1px 2px; }
.omps-card-link { display: flex; align-items: center; gap: 6px; min-width: 0; font-size: 11.5px; color: var(--o-muted); padding-top: 6px; border-top: 1px dashed var(--o-border); }
.omps-card-link-board { font-weight: 600; color: var(--o-fg2); flex: none; }
.omps-card-link-title { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.omps-kstatus { flex: none; display: inline-flex; align-items: center; height: 17px; padding: 0 6px; margin-left: 6px; border-radius: 4px; font-size: 10.5px; font-weight: 600; text-transform: lowercase; background: color-mix(in srgb, var(--o-fg) 9%, transparent); color: var(--o-fg2); }
.omps-card-link .omps-kstatus { margin-left: 0; }
.k-running { background: color-mix(in srgb, var(--o-blue) 18%, transparent); color: var(--o-blue); }
.k-ready { background: color-mix(in srgb, var(--o-purple) 18%, transparent); color: var(--o-purple); }
.k-blocked { background: color-mix(in srgb, var(--o-pink) 18%, transparent); color: var(--o-pink); }
.k-done { background: color-mix(in srgb, var(--o-green) 18%, transparent); color: var(--o-green); }
.k-triage, .k-todo { background: color-mix(in srgb, var(--o-yellow) 16%, transparent); color: var(--o-yellow); }
.omps-card-foot { display: flex; align-items: center; gap: 8px; color: var(--o-muted); font-size: 11.5px; }
.omps-card-state { display: inline-flex; align-items: center; gap: 6px; color: var(--o-fg2); }
.omps-pulse { width: 10px; height: 10px; border-radius: 50%; border: 2px solid var(--t-working); border-top-color: transparent; animation: omps-spin 0.9s linear infinite; }
.omps-progress { width: 46px; height: 4px; border-radius: 2px; background: color-mix(in srgb, var(--o-fg) 12%, transparent); overflow: hidden; display: inline-flex; }
.omps-progress span { display: block; height: 100%; background: var(--o-grad); }
.omps-cost { font-variant-numeric: tabular-nums; color: var(--o-fg2); }
.omps-when { display: inline-flex; align-items: center; gap: 3px; white-space: nowrap; }

/* ---------- empty / error / loading ---------- */
.omps-empty { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 8px; padding: 48px 24px; color: var(--o-muted); }
.omps-empty-icon { width: 46px; height: 46px; border-radius: 14px; display: grid; place-items: center; color: var(--o-fg); background: linear-gradient(135deg, color-mix(in srgb, #ed4abf 22%, transparent), color-mix(in srgb, #5ad8e6 18%, transparent)); border: 1px solid var(--o-border); }
.omps-empty-title { color: var(--o-fg); font-weight: 600; font-size: 15px; }
.omps-empty-body { max-width: 520px; }
.omps-empty-compact { padding: 14px 8px; gap: 5px; }
.omps-empty-compact .omps-empty-icon { width: 28px; height: 28px; border-radius: 9px; background: transparent; color: var(--o-faint); border-style: dashed; }
.omps-empty-compact .omps-empty-title { font-size: 12px; font-weight: 500; color: var(--o-faint); }
.omps-error { display: flex; align-items: flex-start; gap: 8px; padding: 10px 12px; border-radius: var(--o-radius-sm); border: 1px solid color-mix(in srgb, var(--o-red) 45%, transparent); background: color-mix(in srgb, var(--o-red) 10%, transparent); color: var(--o-fg); }
.omps-error > .omps-icon { color: var(--o-red); margin-top: 2px; }
.omps-error-text { flex: 1; white-space: pre-wrap; word-break: break-word; }
.omps-loading { display: flex; align-items: center; justify-content: center; gap: 10px; padding: 60px 0; color: var(--o-muted); }

/* ---------- drawer (detail) ---------- */
.omps-drawer {
	position: fixed; top: 0; right: 0; bottom: 0; z-index: 60;
	width: min(540px, 100vw); display: flex; flex-direction: column;
	background: linear-gradient(var(--o-raised), var(--o-raised)), var(--o-solid); color: var(--o-fg);
	border-left: 1px solid var(--o-border);
	box-shadow: -24px 0 60px -30px rgba(0, 0, 0, 0.6);
	animation: omps-slide 0.16s ease-out;
}
.omps-host-desktop .omps-drawer { position: absolute; }
@keyframes omps-slide { from { transform: translateX(24px); opacity: 0; } }
.omps-drawer-head { display: flex; align-items: flex-start; gap: 10px; padding: 16px 16px 12px 20px; border-bottom: 1px solid var(--o-border); background: linear-gradient(180deg, color-mix(in srgb, var(--o-fg) 3%, transparent), transparent); }
.omps-drawer-titles { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 5px; }
.omps-drawer-title { margin: 0; font-size: 17px; font-weight: 650; line-height: 1.3; color: var(--o-fg); word-break: break-word; }
.omps-drawer-sub { display: flex; align-items: center; gap: 6px; color: var(--o-muted); font-size: 12px; min-width: 0; }
.omps-drawer-sub > span[title] { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
.omps-sep { color: var(--o-faint); }
.omps-state { align-self: flex-start; display: inline-flex; align-items: center; gap: 6px; height: 22px; padding: 0 9px; border-radius: 999px; font-size: 11.5px; font-weight: 600; background: color-mix(in srgb, var(--tone) 15%, transparent); color: var(--o-fg); border: 1px solid color-mix(in srgb, var(--tone) 35%, transparent); }
.omps-drawer-body { flex: 1; min-height: 0; overflow: auto; padding: 16px 20px; display: flex; flex-direction: column; gap: 16px; }
.omps-drawer-foot { border-top: 1px solid var(--o-border); padding: 12px 16px 14px 20px; background: color-mix(in srgb, var(--o-fg) 2%, transparent); }
.omps-section-label { font-size: 11px; font-weight: 650; letter-spacing: 0.06em; text-transform: uppercase; color: var(--o-muted); margin-bottom: 6px; }
.omps-meta { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px 16px; margin: 0; padding: 12px 14px; border-radius: var(--o-radius); border: 1px solid var(--o-border); background: var(--o-card); }
.omps-meta-item { min-width: 0; }
.omps-meta dt { font-size: 11px; color: var(--o-muted); margin: 0 0 2px; }
.omps-meta dd { margin: 0; font-size: 12.5px; color: var(--o-fg); overflow-wrap: anywhere; }
.omps-tags { display: inline-flex; flex-wrap: wrap; gap: 4px; }
.omps-mode-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
.omps-mode-row .omps-section-label { margin: 0; }
.omps-model-picker { display: inline-flex; flex: 1; min-width: 12rem; }
.omps-model-picker .omps-input { width: 100%; }
.omps-default-model { display: flex; align-items: flex-end; gap: 8px; flex-wrap: wrap; margin: 12px 0; }
.omps-default-model .omps-field { flex: 1; min-width: 16rem; margin: 0; }
.omps-question { border-radius: var(--o-radius); padding: 14px; background: linear-gradient(160deg, color-mix(in srgb, var(--o-pink) 14%, transparent), color-mix(in srgb, var(--o-purple) 8%, transparent)); border: 1px solid color-mix(in srgb, var(--o-pink) 40%, transparent); display: flex; flex-direction: column; gap: 12px; }
.omps-q-head { display: flex; gap: 10px; }
.omps-q-icon { color: var(--o-pink); margin-top: 1px; }
.omps-q-titles { min-width: 0; flex: 1; }
.omps-q-title { font-weight: 650; font-size: 14px; color: var(--o-fg); }
.omps-q-detail { margin: 6px 0 0; padding: 7px 9px !important; border-radius: 6px; background: color-mix(in srgb, var(--o-fg) 7%, transparent) !important; white-space: pre-wrap; word-break: break-word; font-size: 12px; }
.omps-q-message { margin-top: 4px; color: var(--o-fg2); white-space: pre-wrap; }
.omps-q-options { display: flex; flex-wrap: wrap; gap: 6px; }
.omps-q-form { display: flex; flex-direction: column; gap: 8px; align-items: flex-end; }
.omps-q-form .omps-input { width: 100%; }
.omps-q-ask { display: flex; flex-direction: column; gap: 12px; align-items: flex-start; }
.omps-q-sub { border: 0; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 7px; width: 100%; }
.omps-q-sub legend { font-weight: 600; margin-bottom: 7px; padding: 0; }
.omps-reply { min-width: 0; }
.omps-md { font-size: 13px; line-height: 1.6; color: var(--o-fg); overflow-wrap: anywhere; }
.omps-md > :first-child { margin-top: 0; }
.omps-md p { margin: 0 0 9px; }
.omps-md h4, .omps-md h5, .omps-md h6 { margin: 14px 0 6px; font-size: 13.5px; font-weight: 650; }
.omps-md ul, .omps-md ol { margin: 0 0 9px; padding-left: 20px; }
.omps-md ul { list-style: disc; }
.omps-md ol { list-style: decimal; }
.omps-md li { margin: 2px 0; }
.omps-md code { padding: 1px 5px !important; border-radius: 4px; background: color-mix(in srgb, var(--o-fg) 9%, transparent) !important; }
.omps-md pre { margin: 0 0 10px; padding: 10px 12px !important; border-radius: 8px; border: 1px solid var(--o-border) !important; background: color-mix(in srgb, var(--o-fg) 5%, transparent) !important; overflow: auto; font-size: 12px; line-height: 1.5; }
.omps-md pre code { padding: 0 !important; background: transparent !important; }
.omps-md blockquote { margin: 0 0 9px; padding-left: 10px; border-left: 3px solid var(--o-border-strong); color: var(--o-fg2); }
.omps-md a { color: var(--o-accent); }
.omps-md em { font-style: italic; }
.omps-md hr { border: 0; border-top: 1px solid var(--o-border); margin: 14px 0; }
.omps-md-table { overflow-x: auto; margin: 0 0 10px; border: 1px solid var(--o-border); border-radius: 8px; }
.omps-md table { border-collapse: collapse; width: 100%; font-size: 12.5px; line-height: 1.45; }
.omps-md th, .omps-md td { padding: 5px 9px; text-align: left; vertical-align: top; border-bottom: 1px solid var(--o-border); }
.omps-md th { font-weight: 600; color: var(--o-fg); background: color-mix(in srgb, var(--o-fg) 4%, transparent); white-space: nowrap; }
/* Cells break between words (the table scrolls sideways when it must), never inside a name or a date. */
.omps-md td { overflow-wrap: normal; }
.omps-md td code { white-space: nowrap; }
.omps-md tr:last-child td { border-bottom: 0; }
.omps-exit { margin-top: 8px; font-size: 12px; color: var(--o-muted); }
.omps-followup { display: flex; flex-direction: column; gap: 8px; }
.omps-followup .omps-input { resize: vertical; min-height: 54px; }
.omps-followup-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.omps-check { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; color: var(--o-fg2); cursor: pointer; }
.omps-confirm { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; color: var(--o-red); }

/* ---------- inputs ---------- */
.omps-input { width: 100%; padding: 7px 10px; border-radius: var(--o-radius-sm); border: 1px solid var(--o-border); background: color-mix(in srgb, var(--o-fg) 3%, var(--o-raised)); color: var(--o-fg); outline: 0; color-scheme: light dark; }
.omps-input::placeholder { color: var(--o-faint); }
.omps-input:focus { border-color: var(--o-ring); box-shadow: 0 0 0 3px color-mix(in srgb, var(--o-ring) 22%, transparent); }
textarea.omps-input { resize: vertical; line-height: 1.5; }
select.omps-input { height: 34px; padding: 0 8px; }
select.omps-input option, select.omps-input optgroup { background: var(--o-raised); color: var(--o-fg); }
.omps-field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.omps-field-label { font-size: 12px; font-weight: 600; color: var(--o-fg2); }
.omps-field-hint { font-size: 11.5px; color: var(--o-faint); }
.omps-field-hint.is-error { color: var(--o-red); }
.omps-models-error { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; margin-top: 4px; word-break: break-word; }
.omps-models-error .omps-btn { color: var(--o-fg2); }

/* ---------- dialog (new session) ---------- */
.omps-backdrop { position: fixed; inset: 0; z-index: 70; display: grid; place-items: center; padding: 24px; background: color-mix(in srgb, #000 45%, transparent); backdrop-filter: blur(3px); animation: omps-fade 0.12s ease-out; }
.omps-host-desktop .omps-backdrop { position: absolute; }
@keyframes omps-fade { from { opacity: 0; } }
.omps-dialog { width: min(640px, 100%); max-height: calc(100% - 16px); display: flex; flex-direction: column; border-radius: 14px; border: 1px solid var(--o-border); background: linear-gradient(var(--o-raised), var(--o-raised)), var(--o-solid); color: var(--o-fg); box-shadow: 0 40px 100px -40px rgba(0, 0, 0, 0.8), 0 30px 120px -60px rgba(155, 77, 255, 0.5); overflow: hidden; }
.omps-dialog-head { display: flex; align-items: center; gap: 10px; padding: 14px 14px 12px 20px; border-bottom: 1px solid var(--o-border); position: relative; }
.omps-dialog-head::after { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 2px; background: var(--o-grad); }
.omps-dialog-head h2 { flex: 1; margin: 0; font-size: 15px; font-weight: 650; display: inline-flex; align-items: center; gap: 8px; }
.omps-dialog-body { padding: 16px 20px; overflow: auto; display: flex; flex-direction: column; gap: 14px; }
.omps-dialog-foot { display: flex; align-items: center; gap: 8px; padding: 12px 16px 14px 20px; border-top: 1px solid var(--o-border); }
.omps-prompt { min-height: 110px; }
.omps-row2 { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 14px; }
.omps-at { display: flex; flex-direction: column; gap: 8px; }
.omps-at-presets { display: flex; flex-wrap: wrap; gap: 6px; }

/* ---------- boards view ---------- */
.omps-boards { display: flex; flex-direction: column; gap: 14px; }
.omps-lane-banner { display: flex; align-items: center; gap: 14px; padding: 14px 16px; border-radius: var(--o-radius); border: 1px solid var(--o-border); background: var(--o-card); }
.omps-lane-banner.is-on { border-color: color-mix(in srgb, var(--o-green) 40%, var(--o-border)); background: linear-gradient(100deg, color-mix(in srgb, var(--o-green) 9%, transparent), var(--o-card) 60%); }
.omps-lane-banner-icon { width: 36px; height: 36px; border-radius: 10px; display: grid; place-items: center; background: color-mix(in srgb, var(--o-fg) 7%, transparent); color: var(--o-fg2); flex: none; }
.omps-lane-banner.is-on .omps-lane-banner-icon { color: var(--o-green); background: color-mix(in srgb, var(--o-green) 14%, transparent); }
.omps-lane-banner.is-warn { border-color: color-mix(in srgb, var(--o-yellow) 45%, var(--o-border)); background: linear-gradient(100deg, color-mix(in srgb, var(--o-yellow) 9%, transparent), var(--o-card) 60%); }
.omps-lane-banner.is-warn .omps-lane-banner-icon { color: var(--o-yellow); background: color-mix(in srgb, var(--o-yellow) 14%, transparent); }
.omps-lane-banner-text { flex: 1; min-width: 0; }
.omps-lane-banner-title { font-weight: 650; font-size: 14px; margin-bottom: 2px; }
.omps-bgrid { display: grid; grid-template-columns: repeat(auto-fill, minmax(380px, 1fr)); gap: 12px; align-items: start; }
.omps-bcard { border-radius: calc(var(--o-radius) + 2px); border: 1px solid var(--o-border); background: var(--o-raised); display: flex; flex-direction: column; overflow: hidden; }
.omps-bcard.is-on { border-color: color-mix(in srgb, var(--o-green) 35%, var(--o-border)); }
.omps-bcard-head { display: flex; align-items: center; gap: 10px; padding: 12px 14px; border-bottom: 1px solid var(--o-border); }
.omps-bcard-icon { width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; color: var(--o-fg2); background: color-mix(in srgb, var(--o-accent) 14%, transparent); flex: none; }
.omps-bcard-name { font-weight: 650; font-size: 14px; }
.omps-bcard-slug { font-size: 11.5px; color: var(--o-muted); font-family: var(--font-mono, ui-monospace, monospace); }
.omps-lane-state { font-size: 11.5px; color: var(--o-muted); }
.omps-lane-state.is-on { color: var(--o-green); font-weight: 600; }
.omps-bcard-form { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 12px; padding: 12px 14px; border-bottom: 1px solid var(--o-border); }
.omps-bcard-form .omps-field:first-child { grid-column: 1 / -1; }
.omps-bcard-save { grid-column: 1 / -1; display: flex; justify-content: flex-end; }
.omps-bcard-cards { padding: 12px 14px; display: flex; flex-direction: column; gap: 4px; }
.omps-linked { list-style: none; margin: 0 0 6px; padding: 0; display: flex; flex-direction: column; gap: 4px; }
.omps-linked-row { display: flex; align-items: center; gap: 8px; min-width: 0; padding: 5px 8px; border-radius: 7px; background: var(--o-card); border: 1px solid var(--o-border); font-size: 12.5px; }
.omps-linked-row .omps-kstatus { margin-left: 0; }
.omps-linked-title { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.omps-linked-session { display: inline-flex; align-items: center; gap: 5px; border: 1px solid var(--o-border); background: transparent; color: var(--o-fg2); border-radius: 999px; padding: 1px 8px; font-size: 11.5px; cursor: pointer; white-space: nowrap; }
.omps-linked-session:hover { border-color: var(--tone); color: var(--o-fg); }
.omps-linked-error { display: inline-flex; align-items: center; gap: 4px; color: var(--o-red); }
.omps-ready { margin-top: 6px; }
.omps-bcard-foot { padding: 8px 14px 10px; font-size: 11.5px; color: var(--o-faint); display: flex; gap: 10px; flex-wrap: wrap; border-top: 1px dashed var(--o-border); }
.omps-bcard-foot:empty { display: none; }

@media (max-width: 720px) {
	.omps-search { min-width: 0; flex: 1; }
	.omps-bgrid { grid-template-columns: 1fr; }
	.omps-meta { grid-template-columns: 1fr; }
}
@media (prefers-reduced-motion: reduce) {
	.omps *, .omps *::before, .omps *::after { animation: none !important; transition: none !important; }
}
`;

// integrations/hermes/ui/desktop.ts
var ROUTE = "/omp-sessions";
var desktop_default = {
  id: "omp-sessions",
  name: "omp Sessions",
  register(ctx) {
    const Page = createPage({
      kind: "desktop",
      React,
      css: style_default,
      request: (path, options) => ctx.rest(path, options?.body === void 0 ? { method: options?.method ?? "GET" } : { method: options.method ?? "POST", body: options.body }),
      // Desktop opens only web links (no vscode://), so the dashboard's redirect page, in the browser.
      openVscode: async (link) => {
        if (!await ctx.os.openExternal(link.page)) throw new Error(`Hermes Desktop did not open the browser. Open this link on this computer: ${link.url}`);
      }
    });
    ctx.registerMany([
      { id: "page", area: ROUTES_AREA, data: { path: ROUTE }, render: () => React.createElement(Page, null) },
      // Kanban's row has order 50.
      { id: "nav", area: SIDEBAR_NAV_AREA, order: 51, data: { path: ROUTE, label: "omp Sessions", codicon: "pulse" } },
      {
        id: "open",
        area: PALETTE_AREA,
        data: { id: "omp-sessions.open", label: "omp Sessions: Open", keywords: ["omp", "sessions", "coding", "agent", "omp-sessions"], run: () => host.navigate(ROUTE) }
      }
    ]);
  }
};
export {
  desktop_default as default
};
